#!/bin/zsh
# P3.6 step 1 (decision 189, Mathis 2026-10-22): Codex sketches the world map rebuilt as floating islands on the
# Flame's level path (inspiration: docs/design/p36/refs/inspiration-floating-islands.png). Two portrait frames, in
# parallel. Plan: docs/plan-2.0/p36-map-islands.md. Re-run safe. In resume-codex.sh.
ROOT="$(cd "$(dirname "$0")/.." && pwd)"; cd "$ROOT"
CODEX="/Applications/ChatGPT.app/Contents/Resources/codex-cli/bin/codex"; D=docs/design/p36; A=prototypes/p2-spikes/SpikeLab/Assets
REFS=(--image $D/refs/inspiration-floating-islands.png --image $D/refs/map-today.png --image $A/thumb-sanctuary.jpg --image $A/thumb-grove.jpg --image $A/thumb-stillwater.jpg --image $A/thumb-highlands.jpg --image $A/thumb-library.jpg --image $A/depth-spark-keyed.png --image docs/design/p33/daily-morning.png)
BASE="Design ONE full-screen iPhone screen (tall portrait, about 1206x2622, status bar at the top): the WORLD MAP of a cozy self-growth fantasy game, completely redesigned. INSPIRATION (first image, a famous mobile game's map): its structure and feel, chunky floating islands in a deep swirling sky, little paths of floating stepping stones with numbered level nodes going from one island to the next. Do not copy that game's characters or style; use OUR game's look: the painterly cel-shaded fantasy style of our current map (second image) and of our worlds (images 3 to 7: Sanctuary, Whispering Grove, Stillwater, Ascent Highlands, Library of Embers), our hero the Spark (eighth image), and our interface (ninth image: serif titles, champagne and gold, cream text, dark cards with a crisp lip). Colours slightly softer, not oversaturated.
THE MAP: a vertical journey that scrolls upward. The background is a deep night-teal to indigo sky with a slow soft swirl, faint stars and drifting mist (the Hush). Each WORLD is one big floating island of rock with its landmark on top and roots and rocks hanging below: the Sanctuary (a round stone circle with a small fountain, broken pillars, wisteria, little waterfalls pouring off the edge), the Whispering Grove (a giant tree full of warm lanterns), the Stillwater (a calm lake with reeds and a small pavilion), the Ascent Highlands (green peaks, a windmill, falls), the Library of Embers (a domed library with books floating around it), the Wilds (lush jungle, ruins), Forge Mountain (a small volcano with a glowing forge). Islands zig-zag left and right up the screen, big and readable. Between consecutive islands, a PATH of small floating stepping-stone tiles; each tile carries a round medallion with a LEVEL NUMBER (the hero's levels, counting up along the path). Passed levels: medallion lit warm gold. Current level: the Spark (our hero, small, glowing) stands on that stone, with a soft glow ring. Levels ahead: dim grey-blue stone. Each island's name on an elegant small nameplate on or just under its island (serif, cream on a dark plate with a gold edge), never covering the landmark. OPEN islands are bright and warm. The NEXT island to unlock glows softly and shows a gold coin badge with its price and a small 'Buy' button. Islands further ahead are veiled in mist, darker, with a small lock and 'Level N'. TOP BAR: a round back button 'Home', the title 'The Emberlands' in serif, and the Ember coin counter on the right (like the current map). It must be buildable in an app: clean layers, no tiny text, no big blurry shadows."
typeset -A DESC
DESC[start]="FRAME: the START of the journey. At the bottom the Sanctuary island (level 1), above it the Whispering Grove island (level 2), then the Stillwater island (level 4) glowing as the next world to buy with a coin badge '150' and a 'Buy' button, and at the top edge the misty, locked Ascent Highlands island ('Level 6'). Path stones numbered 1, 2, 3, 4, 5, 6 between them. The Spark stands on stone 3, between the Grove and the Stillwater. Ember counter shows 205. Save it as $D/map-islands-start.png."
DESC[midway]="FRAME: MIDWAY, scrolled up. At the bottom the Ascent Highlands island (open, level 6), above it the Library of Embers island (level 8, open, books floating), the Spark standing on stone 9 just past the Library, then the Wilds island (level 10) glowing as the next world to buy with a coin badge '450' and 'Buy', and at the top the misty, locked Forge Mountain island ('Level 12'). Path stones numbered 7 to 12. Ember counter shows 480. Save it as $D/map-islands-midway.png."
if (( $# )); then frames=($@); else frames=(start midway); fi
for f in $frames; do
  out=$D/map-islands-$f.png
  [[ -f $out ]] && { echo "exists: $out"; continue; }
  ( "$CODEX" exec -s workspace-write --ephemeral -C "$ROOT" "${REFS[@]}" -- "$BASE
${DESC[$f]} Use your image generation tool. Do not create or edit any other file." < /dev/null > /dev/null 2>&1
    [[ -f $out ]] && echo "done: $out" || echo "MISSING: $out" ) &
done
wait
